// Dávka N – Zvířátka a noc (ježek, šnek, pejsek z útulku, chameleon, velryba, světluška, usínající obec)
window.STORIES_DRAFT = (window.STORIES_DRAFT || []).concat([
  {
    id: 'jezek-mazlik',
    delka: 5,
    pro: 'vse',
    pozn: 'Ježek Pichlík by nejradši všechny objímal, jenže píchá. Dítě ho napadne poradit mu, ať se kamarádů nejdřív zeptá, jak se mazlí oni: zajíc chce sedět vedle sebe, veverka plácnutí tlapkou, žába jen zamávání. S dítětem si ježek pošle pusu po větru. Klidný večerní konec.',
    pouceni: 'Každý má rád jinak, a tak se nejdřív zeptám, jak to chce ten druhý.',
    free: false,
    cats: ['zvirata', 'noc'],
    ages: [2, 6],
    mood: 'lullaby',
    cover: { emoji: '🦔', g1: '#5d4037', g2: '#ffcc80' },
    title: () => `Ježek, který se chtěl mazlit`,
    text: (c) => [
      { t: `Na kraji zahrady, pod hromádkou suchého listí, bydlel malý ježek Pichlík. Měl čumáček černý jako korálek, krátké nožky a na zádech asi šest tisíc bodlinek.` },
      { t: `Pichlík měl jednu velikou slabost. Strašně rád se mazlil. Kdyby mohl, objímal by od rána do večera každého, koho potká.` },
      { t: `Jenže Pichlík byl ježek. A když ježek obejme kamaráda, kamarád řekne jen jedno jediné slovo: „Au!“` },
      { t: `Jednoho večera, když slunce zapadlo za plot a tráva zvlhla rosou, vylezl Pichlík z listí. Ježci chodí ven hlavně večer a v noci. Ve tmě hledají brouky, žížaly a slimáky.` },
      { t: `U plotu seděl zajíc a čistil si ucho. „Ahoj, zajíci!“ zavolal Pichlík a rozběhl se, že ho obejme. „Au!“ vyjekl zajíc a jedním skokem byl na druhém konci zahrady.` },
      { t: `Na nízké větvi seděla veverka. „Ahoj, veverko!“ Pichlík se natáhl, že ji pohladí po ocase. „Au, můj ocásek!“ A veverka vyšplhala až do koruny.` },
      { t: `Na plotě seděl kos. Ten ani nečekal, až Pichlík doběhne. Jen zatřepal křídly a odletěl na střechu.` },
      { t: `Pichlík si sedl do mokré trávy a smutně si funěl do čumáčku. „Já to nedělám schválně,“ šeptal. „Já jen mám všechny rád.“` },
      { t: `Tohle všechno ${c.g('viděl', 'viděla', 'viděli')} z okna ${c.H}.` },
      { t: `S ${c.p1.ins} pak po špičkách ${c.g('vyšel', 'vyšla', 'vyšli')} na zahradu. ${c.g('Dřepl', 'Dřepla', 'Dřepli')} si kousek od ježka. Ne moc blízko. Tak akorát, aby se nelekl.` },
      { t: `${c.H} se ${c.g('zamyslel', 'zamyslela', 'zamysleli')}. Doma se přece taky každý mazlí jinak. Někdo dává pusu, někdo rád hladí po vlasech a někdo chce jen sedět těsně vedle sebe u pohádky.` },
      { t: `„Pichlíku,“ ${c.g('zašeptal', 'zašeptala', 'zašeptali')} potom. „Co kdyby ses kamarádů nejdřív zeptal, jak to mají rádi oni?“` },
      { t: `Pichlík zamrkal. Zeptat se? To ho ještě nikdy nenapadlo.` },
      { t: `Tak se šel zeptat. „Zajíci, jak se mazlíš ty?“ Zajíc chvíli stříhal ušima. „Já mám rád, když si někdo sedne vedle mě a spolu koukáme na měsíc.“` },
      { t: `A tak si sedli vedle sebe, ježek a zajíc, a koukali na měsíc. Bylo to krásné. A vůbec to nepíchalo.` },
      { t: `„A ty, veverko?“ Veverka seskočila o větev níž. „Já mám ráda plácnutí. Tlapka na tlapku, plác!“ Plác! Ježek má bodlinky jen na zádech. Tlapky a bříško má měkké, takže ani tohle nepíchlo.` },
      { t: `U jezírka seděla žába. „A ty, žábo?“ „Já se nemazlím vůbec,“ kvákla žába. „Mně stačí, když na mě zamáváš.“ Tak jí Pichlík zamával. A žába zamávala taky. I to je mazlení, jenom na dálku.` },
      { t: `„A jak se mazlíš ${c.n('ty', 'vy')}?“ zeptal se nakonec Pichlík.` },
      { t: `„${c.n('Já mám', 'My máme')} nejradši pusu na dobrou noc,“ ${c.g('usmál', 'usmála', 'usmáli')} se ${c.H}. „Ale ty jsi divoký ježek a patříš na zahradu. Tak ti ji ${c.n('pošlu', 'pošleme')} po větru.“ Pusa přeletěla zahradou a Pichlík ji chytil přímo na špičku čumáčku.`, sfx: 'sparkle' },
      { t: `Ještě než šli domů, ${c.g('nechal', 'nechala', 'nechali')} u plotu mističku s vodou. S vodou, ne s mlékem. Z mléka ježky bolí bříško.` },
      { t: `Pichlík se spokojeně schoulil do listí. Byl to ten nejmazlivější večer v jeho životě. A ani jednou nikdo neřekl „au“.` },
      { t: `Nad zahradou svítil měsíc. Zajíc spal v trávě, veverka v dutině a žába pod velkým listem u jezírka. Všude bylo ticho.`, sfx: 'owl' },
      { t: `A ${c.n('ty', 'vy')} už ${c.n('ležíš', 'ležíte')} v postýlce. Jak se ${c.n('chceš', 'chcete')} pomazlit dnes? Pusa, pohlazení, nebo jen ruka v ruce, než ${c.n('usneš', 'usnete')}?`, pause: 5 },
      { t: `Pichlík tiše oddechuje pod listím. Bodlinky má uhlazené dozadu, jako když se ${c.n('učešeš', 'učešete')}, a čumáček schovaný. Dobrou noc, Pichlíku. Dobrou noc, ${c.h.voc}.`, pause: 4 },
    ],
  },
  {
    id: 'snek-postak',
    delka: 10,
    pro: 'vse',
    pozn: 'Na Lesní poště pracuje rychlá veverka Fofrnice a nejpomalejší šnek Vendelín („Pomalu, ale jistě“). Dítě rozesílá pozvánky na lesní piknik a dá je rychlé veverce, která je ale schová jako oříšky a zapomene. Dorazí jen pozvánka, kterou nesl šnek. Dítě vymyslí Šnekoveverčí expres: veverka běží a šnek jí z hlavy čte adresy.',
    pouceni: 'Spolehlivost je víc než rychlost: rychle a špatně je pořád špatně.',
    free: false,
    cats: ['zvirata', 'sranda'],
    ages: [3, 8],
    mood: 'adventure',
    cover: { emoji: '🐌', g1: '#33691e', g2: '#dce775' },
    title: () => `Šnek pošťák`,
    text: (c) => [
      { t: `Hluboko v lese, ve starém dutém pařezu, sídlila Lesní pošta. Nad dveřmi visela cedulka z kůry a vedle dveří stála schránka z vydlabané šišky.` },
      { t: `Poštmistrem byl jezevec Hubert. Měl brýle na čumáku, razítko v tlapě a pořádek v každé přihrádce. A měl dva pošťáky.` },
      { t: `První byla veverka Fofrnice. Ta byla rychlá jako vítr. Fíí, a byla na druhém konci lesa. Fíí, a byla zpátky. Než by kdo řekl švec, oběhla Fofrnice třikrát starý dub.`, sfx: 'wind' },
      { t: `Druhý byl šnek Vendelín. A Vendelín byl nejpomalejší pošťák na světě. Za celou hodinu ušel jen pár metrů. A ještě se cestou zastavoval, aby se ujistil, že jde správně.` },
      { t: `Zvířátka se mu trochu smála. „Vendelíne, než doneseš jarní přání, bude z něj vánoční,“ chichotal se zajíc. Ale Vendelín se nezlobil. Jen zvedl tykadla a řekl to, co říkal vždycky: „Pomalu, ale jistě.“` },
      { t: `Vendelín měl totiž svá pravidla. Adresu si vždycky přečetl dvakrát. Oči má šnek na konci tykadel, a tak si každé písmenko pořádně prohlédl zblízka. Dopis nesl na ulitě pod lístkem, aby nezmokl. A nikdy ho nepoložil, dokud nebyl na správném místě.` },
      { t: `Za Vendelínem zůstávala na zemi tenká stříbrná cestička. To je šnečí sliz, po kterém se mu lépe klouže. Zvířátka podle ní vždycky poznala, že u nich byla pošta.` },
      { t: `Jednoho pondělního rána ${c.g('přišel', 'přišla', 'přišli')} k Lesní poště ${c.H}.` },
      { t: `V ${c.n('ruce', 'rukou')} ${c.g('nesl', 'nesla', 'nesli')} hromádku pozvánek nakreslených pastelkami. Na každé byl velký dub, sluníčko a pod tím šest teček. Do neděle totiž zbývalo přesně šest dní. V neděli večer měl být pod starým dubem velký lesní piknik.` },
      { t: `Pozvánky ${c.g('kreslil', 'kreslila', 'kreslili')} u kuchyňského stolu, zrovna když se chystalo to nejlepší jídlo na světě: ${c.food}. A tak všechny pozvánky trochu voněly.` },
      { t: `„Já je roznesu!“ vyskočila Fofrnice. „Do oběda je budou mít všichni!“` },
      { t: `„Do neděle to stihnu taky,“ řekl klidně Vendelín. „Pomalu, ale jistě.“` },
      { t: `${c.H} ${c.g('chvilku přemýšlel', 'chvilku přemýšlela', 'chvilku přemýšleli')}. Do oběda zní líp než do neděle. A tak ${c.g('dal', 'dala', 'dali')} skoro všechny pozvánky veverce.` },
      { t: `Jen jednu ne. Tu pro žábu Kuňku, která bydlela u rybníka na druhém konci lesa. „K rybníku nechodím,“ ošívala se Fofrnice. „Je tam mokro a já si nerada máčím ocas.“` },
      { t: `„Já mokro mám rád,“ rozzářil se Vendelín. Vzal pozvánku, přečetl adresu jednou, pak podruhé, schoval si ji na ulitu pod lístek a vyrazil. Pomalu, ale jistě.` },
      { t: `Fofrnice byla zpátky za hodinu. „Hotovo!“ hlásila a ani se nezadýchala. Vendelín byl v tu dobu u první šišky za pařezem.` },
      { t: `Jezevec Hubert jí na tlapku dal razítko s nápisem Výborně. Zvířátka tleskala. A zajíc volal směrem k šišce: „Vendelíne, nepotřebuješ postrčit?“ „Nepotřebuju,“ ozvalo se zpoza šišky. „Pomalu, ale jistě.“` },
      { t: `V úterý se Vendelín dostal k potoku. Ve středu pršelo a Vendelín byl šťastný jako nikdy, protože šneci mají déšť nejradši. Ve čtvrtek pálilo slunce, a tak se zavřel do ulity a počkal, až se ochladí.` },
      { t: `Ve čtvrtek odpoledne si k němu přisedla straka. „Ty se ale vlečeš,“ zaskřehotala. „Dej mi ten dopis. Já ho donesu za chvilku, a ty mi za to dáš něco lesklého.“` },
      { t: `Vendelín se na ni podíval jedním tykadlem, pak druhým. „Děkuju, ale dopis z ulity nepustím. Slíbil jsem, že ho donesu já.“ Straka jen pokrčila křídly a odletěla. Na dopis by stejně zapomněla, sotva by uviděla první lesklý knoflík.` },
      { t: `V pátek lezl přes mech a zpíval si: „Pomalu, ale jistě, po mechu i po listí.“ V sobotu lezl přes kořeny. A v neděli ráno zaťukal ulitou na dveře u rybníka. Ťuk, ťuk. „Pošta pro žábu Kuňku. Adresa sedí.“` },
      { t: `V neděli večer ${c.g('stál', 'stála', 'stáli')} pod starým dubem ${c.H}. ${cap(c.p1.nom)} ${c.p1.g('nesl', 'nesla')} košík.` },
      { t: `Deka byla rozložená, jídlo připravené a lucernička rozsvícená. Kdo přišel? Žába Kuňka. S pozvánkou v tlapce, suchou, celou a se stříbrným razítkem od šnečí cestičky. A na zádech jí seděl Vendelín, protože žába skáče přece jen rychleji než šnek. Kuňka byla nadšená. Ještě nikdy nedostala pozvánku, která by tak krásně voněla.` },
      { t: `Čekali a čekali. Zajíc nepřišel. Sova nepřišla. Krtek, srnka ani ježek nepřišli. Lucernička svítila do prázdna.` },
      { t: `„Fofrnice,“ ${c.g('zeptal', 'zeptala', 'zeptali')} se opatrně. „Kam jsi vlastně dala ty pozvánky?“` },
      { t: `Fofrnice zčervenala až po špičky uší. „No… nejdřív jsem je chtěla roznést. Ale pak jsem si je jen na chvilku schovala. Jako oříšky. Do mechu, pod kořeny, do díry v buku…“` },
      { t: `Veverky to tak opravdu dělají. Na podzim schovají spoustu oříšků po celém lese a na některé pak zapomenou. Z těch zapomenutých někdy vyrostou nové stromy. Z pozvánek ale nevyroste nic. To už Fofrnice zkoušela.` },
      { t: `„A ty, co jsi neschovala?“ „Ty jsem doručila,“ počítala Fofrnice na tlapce. „Sovinu jsem strčila do krtčí hromádky. Krtkovu jsem dala nahoru do sovího stromu. A zajícova je… asi u něčeho hnědého.“` },
      { t: `Všichni se rozhlédli. V lese je hnědé skoro všechno. Hnědé listí, hnědé šišky, hnědé houby a hnědý jezevec Hubert. Ten se trochu urazil.` },
      { t: `${c.H} si ${c.g('sedl', 'sedla', 'sedli')} na kořen a ${c.g('přemýšlel', 'přemýšlela', 'přemýšleli')}.` },
      { t: `Co umí Fofrnice? Běhat rychle a najít schované oříšky čumákem. A co umí Vendelín? Číst adresy pořádně a nic neztratit. Jeden je rychlý a druhý spolehlivý. Kdyby tak byli dohromady…` },
      { t: `A pak si ${c.g('vzpomněl', 'vzpomněla', 'vzpomněli')}: pozvánky přece voní! „Fofrnice, ty najdeš oříšek čumákem i pod sněhem. Najdeš i voňavou pozvánku?“` },
      { t: `Fofrnice začichala. Čuch, čuch. „Voní to tamhle! A tamhle taky!“ A už se chystala vystřelit.` },
      { t: `„Stůj!“ ${c.g('zavolal', 'zavolala', 'zavolali')} ${c.H}. „Nepoběžíš sama. Vezmeš s sebou Vendelína.“` },
      { t: `A tak vznikl Šnekoveverčí expres. Vendelín se usadil Fofrnici na hlavu, mezi ouška, jako malý kapitán. Fofrnice běžela a Vendelín četl. Každou adresu dvakrát.`, sfx: 'wind' },
      { t: `„Doleva!“ hlásil Vendelín. „Teď doprava! Stůj, tady bydlí krtek. Adresa sedí. Doručit!“ A Fofrnice běžela, až se jí ocas vlnil jako vlajka.` },
      { t: `Najednou to šlo rychle i správně. Sova dostala svou pozvánku, krtek svou a zajícova se našla pod hnědou houbou, hned vedle hnědého pařezu u hnědé cestičky.`, sfx: 'paper' },
      { t: `Jen pozvánka pro srnku dala práci. Ležela v díře v buku a na ní spala malá myška. Přikrývala se jí jako peřinkou. Vendelín zaťukal, myška se omluvila a dostala za odměnu lístek s obrázkem, aby měla čím se přikrývat dál.` },
      { t: `Než se úplně setmělo, seděli pod dubem všichni. Zajíc, sova, krtek, srnka, ježek, žába Kuňka, Fofrnice i Vendelín. Sova přiletěla moc ráda. Pro sovy je totiž večer to pravé ráno.`, sfx: 'owl' },
      { t: `Fofrnice si olízla tlapku a povzdechla si. „Rychle to bylo, ale k ničemu. Kdo nic nedoručí, je pomalý, i když běží.“` },
      { t: `Jezevec Hubert si nasadil brýle, odkašlal si a připíchl Vendelínovi na ulitu lesklý knoflík. Byla to medaile. Stálo na ní: Za spolehlivost. Zajíc tleskal ze všech nejvíc a už se ani trochu nesmál.` },
      { t: `Od té doby jezdí Lesní poštou Šnekoveverčí expres. Fofrnice běží a Vendelín čte. A když se jich někdo zeptá, jak to dělají, každý odpoví kousek. „Rychle!“ volá Fofrnice. „Ale jistě,“ dodá Vendelín.` },
      { t: `A za týden přišel ${c.h.dat} dopis.` },
      { t: `Byl napsaný na lístku a nesl ho Vendelín, sám, pěšky. Šel s ním celý týden. Stálo v něm jen: „Děkuju. Pomalu, ale jistě. ${c.n('Tvůj', 'Váš')} Vendelín.“`, sfx: 'ding' },
    ],
  },
  {
    id: 'pejsek-z-utulku',
    delka: 10,
    pro: 'vse',
    pozn: 'Rodina si jede do útulku pro pejska. Plachá fenka Ponožka si je vybere sama, když se s ní dítě seznámí „po psím“. Doma se schová pod stůl, a tak dítě s rodiči píše psí slovníček (zívání, olizování čumáku, vrtění celým zadkem, hravý luk) a čeká. Venčí se i v dešti. Nakonec Ponožka přijde sama a večer usne spokojená.',
    pouceni: 'Zvíře není hračka: potřebuje péči každý den, i když se nechce, a hlavně trpělivost a čas, aby si zvyklo.',
    free: false,
    cats: ['zvirata', 'zivot'],
    ages: [3, 8],
    mood: 'lullaby',
    cover: { emoji: '🐶', g1: '#8d6e63', g2: '#ffe0b2' },
    title: () => `Pejsek z útulku`,
    text: (c) => [
      { t: `Ten den se ${c.H} ${c.g('vzbudil', 'vzbudila', 'vzbudili')} dřív než budík.`, sfx: 'birds' },
      { t: `Dřív než kos za oknem. Dokonce dřív než slunce. Dneska se totiž mělo jet pro pejska. Ne pro plyšového a ne pro pejska z knížky. Pro opravdového, živého pejska, který bude bydlet s nimi.` },
      { t: `Nejoblíbenější zvíře ${c.h.gen}? To ví každý: ${c.animal}. Ale tohle bylo něco jiného. Tohle měl být kamarád do rodiny.` },
      { t: `Celý týden se na to doma chystali. Psali si psí seznam. Pelíšek do klidného kouta. Dvě misky, jednu na vodu a jednu na granule. Vodítko. A jeden slib: pejsek musí ven ráno, odpoledne i večer, i když bude pršet. I když se nebude chtít.` },
      { t: `${c.H} ${c.g('slíbil', 'slíbila', 'slíbili')}, že u toho ${c.n('bude', 'budou')} pokaždé.` },
      { t: `„Pejsek není hračka,“ ${c.p1.g('řekl', 'řekla')} ještě ${c.p1.nom}.` },
      { t: `„Hračku ${c.n('můžeš', 'můžete')} dát do skříně, když ${c.n('tě', 'vás')} omrzí. Pejska ne. Ten s námi bude každý den, třeba i patnáct let.“` },
      { t: `Útulek byl na kraji lesa, za vysokým plotem. Už u brány bylo slyšet: haf, haf, vrr, haf! Štěkalo tam snad sto psů najednou.` },
      { t: `U brány je přivítala paní ošetřovatelka. Měla zelenou bundu, v kapse piškoty a na kalhotách chlupy od všech psů v útulku. „Tady bydlí pejsci, kteří čekají na nový domov,“ řekla. „Pojďte se podívat.“` },
      { t: `V prvním kotci skákal velký černý pes skoro až ke stropu. Ve druhém se točila malá chlupatá kulička a chytala si ocas. Ve třetím ležel starý pán pes a chrápal.` },
      { t: `„Jak se sem všichni dostali?“ zeptal se někdo. Paní ošetřovatelka pokrčila rameny. „Někteří se ztratili. A některé přestali lidé chtít. Hodně pejsků k nám přijde po Vánocích. Někdo dostal štěně jako dárek, a když štěně vyrostlo a chtělo ven i v zimě a v dešti, už ho nechtěl.“` },
      { t: `Bylo to trochu smutné. Ale ošetřovatelky se tu o pejsky staraly moc hezky. Venčily je, česaly a každému říkaly jménem. A čekaly s nimi, až pro ně někdo přijde napořád.` },
      { t: `A v posledním kotci, úplně vzadu v rohu, seděla malá hnědá fenka. Jednu tlapku měla bílou, jako by si zapomněla sundat ponožku.` },
      { t: `„To je Ponožka,“ řekla paní ošetřovatelka. „Je tu nová a ještě se trochu bojí.“` },
      { t: `${c.H} ${c.g('chtěl', 'chtěla', 'chtěli')} hned strčit ${c.n('ruku', 'ruce')} mřížkou a Ponožku pohladit.` },
      { t: `Paní ošetřovatelka ale zavrtěla hlavou. „Se psem se seznamuje po psím. Psi nemají rádi, když se jim někdo dlouho dívá do očí. Je lepší sednout si bokem, natáhnout ruku hřbetem napřed a počkat. Pes si nejdřív čumákem přečte, kdo to je. A pak se rozhodne sám.“` },
      { t: `Tak si ${c.g('sedl', 'sedla', 'sedli')} na zem bokem k mřížce, ${c.g('natáhl', 'natáhla', 'natáhli')} ${c.n('ruku', 'ruce')} a ${c.g('čekal', 'čekala', 'čekali')}. Jedna minuta. Dvě minuty. Tři.` },
      { t: `Ponožka zvedla čumák. Udělala krůček. Pak další. Opatrně očichala prsty, jeden po druhém. Čuch, čuch. A pak, docela potichu, olízla malíček.` },
      { t: `„Tak,“ usmála se paní ošetřovatelka. „Myslím, že si vás vybrala.“` },
      { t: `Doma ale Ponožka zalezla pod kuchyňský stůl. A nevylezla. Ani když jí ukázali pelíšek. Ani když zachrastili míčkem s rolničkou. Ani když jí nabídli piškot.` },
      { t: `První noc spala Ponožka pod stolem. Nikdo ji odtamtud nevytahoval. Jen jí k stolu přisunuli pelíšek a dali do něj starý svetr, který voněl celou rodinou. Podle vůně se pes učí, kde je doma.` },
      { t: `${c.H} ${c.g('byl', 'byla', 'byli')} ${c.g('smutný', 'smutná', 'smutní', 'smutné')}.` },
      { t: `„Ona ${c.n('mě', 'nás')} nemá ráda.“` },
      { t: `„Ale má,“ ${c.p1.g('pohladil', 'pohladila')} ${c.g('ho', 'ji', 'je')} ${c.p1.nom}.` },
      { t: `„Jenom je pro ni všechno nové. ${c.n('Pamatuješ', 'Pamatujete')} si na první den ve školce? Tak nějak se teď cítí Ponožka. Potřebuje čas.“` },
      { t: `A tak ${c.H} ${c.g('začal', 'začala', 'začali')} psát psí slovníček.` },
      { t: `Kdo ještě neumí psát, může kreslit, obrázky to řeknou stejně dobře. Do slovníčku se zapisovalo, co Ponožka dělá a co tím asi chce říct.`, sfx: 'paper' },
      { t: `Strana jedna: Když pes zívá, i když není ospalý, znamená to, že je mu všeho trochu moc. Ponožka pod stolem zívala pořád. A tak se doma mluvilo tišeji.` },
      { t: `Strana dvě: Když si pes olizuje čumák a uhýbá pohledem, je nejistý. Tak ho nikdo netahal ven. Miska s vodou stála kousek od stolu, kdyby měla žízeň.` },
      { t: `Strana tři: Když pes jí nebo spí, nikdo ho neruší. To platí u psů úplně stejně jako u lidí. Hlavně u dědečků po obědě.` },
      { t: `Druhý den ráno pršelo. Kapky bubnovaly na okno a z peřiny se vůbec nechtělo. Jenže pejsek se nemůže vyčůrat do nočníku. A slib je slib.` },
      { t: `Tak ${c.H} ${c.g('natáhl', 'natáhla', 'natáhli')} ${c.n('pláštěnku', 'pláštěnky')} a gumáky.` },
      { t: `Vodítko ${c.g('držel', 'držela', 'drželi')} spolu s ${c.p1.ins}.` },
      { t: `I malý pes totiž umí zatáhnout silněji, než by člověk čekal. Ponožka čichala ke každému patníku, každé kaluži a každému stéblu. Pro psa je procházka jako noviny. Čumákem si přečte, kdo tudy šel a co je nového.` },
      { t: `Strana čtyři: Když pes vrtí ocasem, nemusí to vždycky znamenat radost. Ale když vrtí celým zadkem, i s ušima, je šťastný. Ponožka poprvé vrtěla celým zadkem v kaluži. A po dešti tak krásně voněl vzduch, že se domů skoro nikomu nechtělo.` },
      { t: `Ve středu šli všichni k paní veterinářce. Ta Ponožku prohlédla, poslechla jí srdíčko a zkontrolovala čip, malinké zrníčko pod kůží, podle kterého se pozná, komu pes patří. Ponožka se třásla, ale vydržela. Dostala za to piškot a pochvalu.` },
      { t: `„Granule dávejte odměrkou, ne víc, i když bude dělat smutné oči,“ řekla paní veterinářka. „A nikdy jí nedávejte čokoládu. Co je pro děti dobrota, to psům škodí.“ Doma se to hned zapsalo do slovníčku, velkým písmem a s vykřičníkem.` },
      { t: `Každý den vylezla zpod stolu o kousek dál. V úterý k misce. Ve středu ke dveřím. Ve čtvrtek až na koberec, kde se stavěly kostky. Nikdo ji nevolal a nikdo ji netahal. Jen se na ni každý, kdo šel kolem, tiše usmál.` },
      { t: `A v pátek se to stalo. Ponožka přišla až k ${c.h.dat}.` },
      { t: `Přední tlapky položila na zem, zadek vystrčila nahoru a ocas se jí točil jako vrtulka. Poskočila dopředu, pak dozadu a podívala se na míček. Pak zase nahoru, do očí. Pak zase na míček.` },
      { t: `To nemohlo znamenat nic jiného. Strana pět, ta nejhezčí: Když pes udělá luk, předek dolů a zadek nahoru, zve tě na hru.` },
      { t: `A tak si hráli. Míček sem, míček tam. Ponožka ho přinesla, pustila a zase přinesla. Celá kuchyně se smála.`, sfx: 'ding' },
      { t: `Když se Ponožka unavila, lehla si na bok a nastavila bříško. To bylo ve slovníčku taky. Pes, který ukáže bříško, říká: Věřím ti. Tak ji ${c.H} pomalu ${c.g('podrbal', 'podrbala', 'podrbali')}. Ponožka u toho blaženě zavřela oči.` },
      { t: `Večer si Ponožka sama, bez volání, lehla do pelíšku. Pelíšek stál kousek od dveří pokojíčku, aby slyšela, že všichni dýchají a jsou doma.` },
      { t: `${c.H} se ještě ${c.g('naklonil', 'naklonila', 'naklonili')} z postele.` },
      { t: `Ponožka zvedla hlavu, zhluboka vzdychla a položila si bradu na bílou tlapku. Oči se jí pomalu zavíraly.` },
      { t: `Ještě jedna strana do slovníčku. Ta úplně poslední. Když pes vzdychne a položí hlavu na tlapky, znamená to: Tady je mi dobře. Tady jsem doma.`, pause: 3 },
      { t: `Dobrou noc, Ponožko. Dobrou noc, ${c.h.voc}.`, pause: 4 },
    ],
  },
  {
    id: 'chameleon',
    delka: 10,
    pro: 'vse',
    pozn: 'Chameleon Kamil v zoo se schovává mezi listy, protože se mu kdysi někdo zasmál, a zkouší být barevný jako papoušek nebo plameňák. Dítě ho trpělivě najde, od chovatelky zjistí, že chameleoni barvou ukazují hlavně to, jak se cítí, a připomene Kamilovi, co všechno umí. Kamil se rozzáří vlastními barvami a přestane se schovávat.',
    pouceni: 'Nemusím vypadat jako ostatní; nejvíc zazářím, když se nebojím ukázat, jaký opravdu jsem.',
    free: false,
    cats: ['zvirata'],
    ages: [3, 8],
    mood: 'adventure',
    cover: { emoji: '🦎', g1: '#00897b', g2: '#ffb74d' },
    title: () => `Chameleon, který chtěl být vidět`,
    text: (c) => [
      { t: `V zoologické zahradě je pavilon, kde je teplo jako v létě, i když venku sněží. Voní to tam vlhkou hlínou a listím. A v jednom skleněném teráriu tam bydlel chameleon Kamil.` },
      { t: `V pavilonu bydlela spousta zvířat. Papoušci, kteří se hádali o banán. Želvy, které se nikam nehnaly. A opice, které dělaly největší rámus ze všech. Chameleoni pocházejí z teplých krajů, hlavně z Afriky a z ostrova Madagaskar, a tak se tu Kamilovi líbilo.` },
      { t: `Kamil měl oči jako dvě malé věžičky. Každé z nich se umělo dívat jinam. Jedním okem koukal nahoru na strop a druhým dolů na lidi. A to zároveň!` },
      { t: `Každé ráno chodila do pavilonu paní chovatelka s rozprašovačem. Pšt, pšt, a na listech se třpytily kapky. Chameleoni totiž nepijí z misky. Pijí kapky z listů, jednu po druhé, jako když se sbírají korálky.` },
      { t: `Na skle jeho terária visela cedulka: Chameleon. Zkuste ho najít!` },
      { t: `A to byl ten problém. Nikdo ho nenašel. Kamil byl zelený jako listy kolem, a tak lidé jen chvilku koukali, řekli „tady nic není“ a šli dál k opicím.` },
      { t: `„Tady něco je,“ šeptal Kamil za nimi. „Tady jsem já.“ Ale nikdo ho neslyšel.` },
      { t: `Kdysi, když byl Kamil úplně malý, se před teráriem někdo zasmál: „Jé, ten má ale vykulené oči!“ Kamilovi bylo hrozně. A od té doby se schovával. Zelený mezi zelenými listy, aby se mu už nikdo nesmál.` },
      { t: `Jenže schovávat se pořád, to je smutné. Kamil chtěl, aby ho někdo viděl. Ale ne kvůli očím. Chtěl být krásný jako ostatní zvířata v pavilonu.` },
      { t: `Zkusil být červený jako papoušek ze sousedství. Napnul se, zatajil dech… a zhnědl. Lidé si mysleli, že je to klacík.` },
      { t: `Zkusil být růžový jako plameňáci na plakátu. Zatlačil, zafuněl… a zhnědl ještě víc. Klacík, řekli lidé. Kamil si povzdechl a byl zase zelený.` },
      { t: `Jednoho deštivého dne ${c.g('přišel', 'přišla', 'přišli')} do pavilonu ${c.H} s ${c.p1.ins}.`, sfx: 'birds' },
      { t: `Ostatní děti u terária chvilku koukaly, pak řekly „nic tu není“ a utíkaly k opicím.` },
      { t: `Ale ${c.H} ${c.g('zůstal', 'zůstala', 'zůstali')}.` },
      { t: `Na hledání se nemá spěchat, to ví každý, kdo hrál schovávanou. Listy, listy, větvička. Listy, větvička, list… a tenhle list má oko! Jeden malý zelený list se pomalu otočil nahoru. A kousek vedle něj se druhý list otočil dolů.` },
      { t: `„${c.n('Já tě vidím', 'My tě vidíme')}!“ ${c.g('zašeptal', 'zašeptala', 'zašeptali')} ${c.H}.` },
      { t: `Kamil se tak lekl, že ztmavl skoro do černa. Chameleoni totiž tmavnou, když se bojí. „${c.n('Ty mě vidíš', 'Vy mě vidíte')}?“ zašeptal. „A ${c.n('nebudeš', 'nebudete')} se smát mým očím?“` },
      { t: `„Tvým očím?“ ${c.g('podivil', 'podivila', 'podivili')} se. „Vždyť jsou úžasné. Koukáš jedním nahoru a druhým dolů. To nikdo z nás neumí.“` },
      { t: `„Jenže já neumím být barevný,“ posmutněl Kamil. „Zkoušel jsem být červený jako papoušek a růžový jako plameňák. A vždycky z toho byl jen hnědý klacík.“` },
      { t: `Kousek dál krmila paní chovatelka želvy. ${c.H} se ${c.g('zeptal', 'zeptala', 'zeptali')}, jak to chameleoni s barvami vlastně dělají.` },
      { t: `Paní chovatelka si dřepla. „To je dobrá otázka. Lidi si myslí, že se chameleon přebarví podle toho, kde zrovna sedí. Ale tak to není. Kdyby si sedl na šachovnici, šachovnice z něj nebude.“` },
      { t: `„Chameleoni mají v kůži drobounké krystalky, malinké jako prach, a umějí je posouvat. Barva pak ukazuje hlavně to, jak se chameleon cítí. Když je klidný, bývá zelený. Když se bojí nebo mu je zima, ztmavne. A když je šťastný nebo rozrušený, rozzáří se všemi barvami.“` },
      { t: `„Zelená je jejich klidná barva,“ dodala paní chovatelka. „V přírodě se v ní dobře schovají před ptáky a hady. Ale tady v zoo se Kamil schovávat nemusí. Tady mu nikdo neublíží.“` },
      { t: `${c.H} se ${c.g('zamyslel', 'zamyslela', 'zamysleli')}.` },
      { t: `Takže chameleon se nemůže přebarvit na papouška. Ale může ukázat, jaký je uvnitř. Jenže jak se má Kamil rozzářit, když je pořád schovaný a smutný?` },
      { t: `„A co když se mi zase budou smát?“ šeptal Kamil. „Tak tu ${c.n('budu', 'budeme')} s tebou,“ zněla odpověď. „A ${c.n('budu', 'budeme')} se smát s tebou, ne tobě.“` },
      { t: `„Kamile,“ ${c.g('zašeptal', 'zašeptala', 'zašeptali')} potom. „Víš, co všechno umíš?“` },
      { t: `„Umíš chodit po větvi a nohy máš jako kolíčky na prádlo, takže se udržíš i na tenké větvičce. Ocasem si uděláš smyčku a držíš se jím jako rukou. A tvůj jazyk vystřelí rychleji, než člověk stihne mrknout. Je skoro tak dlouhý jako ty celý!“` },
      { t: `Kamil poslouchal. A jak poslouchal, něco se mu dělo s kůží. Nejdřív se mu rozsvítily tváře. Pak se mu po bocích objevil tyrkysový pruh. Pak oranžová skvrnka. A nakonec žlutá pusa, jako by se usmíval banánem.`, sfx: 'magic' },
      { t: `Kamil svítil jako duha po dešti. Ne jako papoušek. Ne jako plameňák. Jako Kamil.` },
      { t: `Zrovna v tu chvíli přišla paní chovatelka s krabičkou cvrčků. Otevřela víčko terária a jeden cvrček skočil na větev. Kamil zamířil oběma očima najednou, a šlup! Jazyk vystřelil a cvrček byl pryč dřív, než kdokoli stihl mrknout.` },
      { t: `„Podívejte!“ volaly děti, které se právě vracely od opic. „Tady je chameleon! A je nádherný!“ U terária se hned udělal hlouček.` },
      { t: `„Jé, ten má ale vykulené oči!“ zvolal jeden kluk. Kamil sebou trhl. Přesně tohle slyšel tenkrát. Jenže kluk pokračoval: „A každým kouká jinam! To je paráda! Já bych taky chtěl koukat na dvě strany.“` },
      { t: `Kamil zůstal překvapeně viset na větvi. Tenkrát se možná nikdo nesmál jemu. Možná se jen někdo divil. Jenže on se tehdy schoval tak rychle, že se to nikdy nedozvěděl.` },
      { t: `Jenže tolik lidí najednou, to bylo na Kamila moc. Začal tmavnout. Zelená, hnědá, skoro šedá. Už se chystal zalézt za list.` },
      { t: `${c.g('Naklonil', 'Naklonila', 'Naklonili')} se blíž a tiše ${c.g('řekl', 'řekla', 'řekli')}: „Kamile, nemusíš svítit pořád. Když jsi zelený, jsi to taky ty. Jen se neschovávej.“` },
      { t: `Kamil se nadechl. Pomalu a opatrně přelezl na přední větvičku, kde byl dobře vidět. Byl zelený, s malinkým tyrkysovým proužkem. A neschoval se.` },
      { t: `Druhý den paní chovatelka cedulku vyměnila. Teď na ní stálo: Chameleon Kamil. Sedí na přední větvičce. Když se na něj usmějete, možná se rozzáří.`, sfx: 'paper' },
      { t: `A Kamil? Někdy je zelený, někdy pruhovaný a někdy oranžový od špičky ocasu až po bradu. Podle toho, jak se zrovna cítí. Ale vždycky sedí na přední větvičce, kde ho všichni vidí.` },
      { t: `${c.H} ${c.g('zamával', 'zamávala', 'zamávali')} na rozloučenou.` },
      { t: `Kamil se podíval jedním okem dopředu a druhým za nimi. A na chvilku zčervenal na špičce ocasu. V chameleonské řeči to asi znamená: „Ahoj a ${c.n('přijď', 'přijďte')} zas.“` },
      { t: `Večer v posteli ${c.g('přemýšlel', 'přemýšlela', 'přemýšleli')} ${c.H}, jakou barvu by ${c.g('měl', 'měla', 'měli')} ${c.n('jako chameleon', 'jako chameleoni')}.` },
      { t: `Ráno, když se těšíš na výlet, by to byla oranžová. Když se zlobíš, červená. Když je smutno, šedivá. A teď, pod peřinou, když se víčka zavírají? Teď by to byla ta nejměkčí a nejospalejší zelená. Jako list, na kterém v noci spí chameleon.` },
      { t: `A jakou barvu ${c.n('máš', 'máte')} dneska ${c.n('ty', 'vy')}?`, pause: 4 },
      { t: `Ať je jakákoli, je to ta správná. I ospalá zelená je moc hezká barva. Dobrou noc, Kamile. Dobrou noc, ${c.h.voc}.`, pause: 4 },
    ],
  },
  {
    id: 'velryba-zpevacka',
    delka: 15,
    pro: 'f',
    pozn: 'Přes mušli se dítě dostane na moře na záda mladé velryby keporkaka Zvonilky. Velkou hlubokou píseň zpívají keporkačí pánové, Zvonilka zpívá vysoko a jinak a starý Hlubák ji okřikuje. Když se ztratí mládě Šplouch, Velká píseň zní ze všech stran a mládě se podle ní nemůže řídit. Dítě požádá sbor o ticho, mušlí uslyší mládě a vymyslí, ať Zvonilka zpívá svou jedinečnou písničku, podle které maminka mládě najde. Fakta o keporkacích (dýchání, ploutve, mléko, šeptání maminek, měnící se píseň) jsou pravdivá.',
    pouceni: 'Odlišnost je dar: to, co mě dělá jiným, může být přesně to, co ostatní jednou potřebují.',
    free: false,
    cats: ['zvirata', 'dobro'],
    ages: [4, 9],
    mood: 'adventure',
    cover: { emoji: '🐋', g1: '#0d47a1', g2: '#80deea' },
    title: () => `Velryba, která zpívala jinak`,
    text: (c) => [
      { t: `V pokojíčku na poličce ležela velká mušle. Uvnitř růžová, zvenku hrbolatá a tak velká, že by se do ní vešla celá dlaň.` },
      { t: `${cap(c.p1.nom)} kdysi ${c.p1.g('říkal', 'říkala')}, že když si ji člověk přiloží k uchu, uslyší moře.` },
      { t: `Ten večer si ji ${c.H} ${c.g('přiložil', 'přiložila', 'přiložili')} k uchu.` },
      { t: `Šššš, šumělo to. Jako vlny. Jako vítr. A pak, docela zdaleka, se ozvalo něco jiného. Písnička. Vysoká a jasná, jako když cinká zvoneček pod vodou. Cink, ciri, cink.`, sfx: 'sparkle' },
      { t: `${c.g('Zavřel', 'Zavřela', 'Zavřeli')} oči, aby ${c.g('slyšel', 'slyšela', 'slyšeli')} líp. A když je zase ${c.g('otevřel', 'otevřela', 'otevřeli')}, kolem nebyl pokojíček. Kolem bylo moře. Teplé, tiché a stříbrné od měsíce. Mušli ${c.g('držel', 'držela', 'drželi')} pořád v ruce.`, sfx: 'magic' },
      { t: `Pod sebou ${c.g('měl', 'měla', 'měli')} něco hladkého, tmavého a obrovského, co se pomalu houpalo na vlnách. Fííí! Kousek vpředu vystříkla do vzduchu fontána a na tvářích to studilo jako sprška.` },
      { t: `To vydechla velryba. ${c.H} ${c.g('seděl', 'seděla', 'seděli')} na velrybích zádech!` },
      { t: `Velryby nejsou ryby. Dýchají vzduch, stejně jako lidé, jen nos mají nahoře na hlavě. Když se vynoří, vyfouknou starý vzduch, až to zahvízdá, a rychle se nadechnou nového.` },
      { t: `„Ahoj,“ ozvalo se zespodu. „Já jsem Zvonilka. ${c.g('Slyšel', 'Slyšela', 'Slyšeli', 'Slyšely')} ${c.n('jsi', 'jste')} mě v mušli, ${c.n('viď', 'viďte')}?“ A hned dodala: „${c.n('Neboj', 'Nebojte')}, potápět se nebudu. Dokud mi sedí někdo na zádech, plavu jen po hladině.“` },
      { t: `Zvonilka byla mladá velryba keporkak. Po stranách měla dlouhé bílé ploutve, skoro jako křídla. Keporkaci mají nejdelší ploutve ze všech velryb. Když s nimi Zvonilka mávla, vypadalo to, že pod vodou letí.` },
      { t: `„A ${c.n('podívej', 'podívejte')} se na můj ocas,“ řekla Zvonilka a zvedla ho nad hladinu. Zespodu byl bílý a měl na sobě černé skvrnky, jako by ho někdo pocákal inkoustem. Každý keporkak má ocas zespodu jiný. Podle něj se dají velryby poznat, jako lidé podle otisku prstu.` },
      { t: `Z hloubky se ozývalo ještě něco dalšího. Hluboké, dlouhé a pomalé. Úúú, óóó, mmmm. Znělo to, jako by zpívalo samo moře.` },
      { t: `„To je Velká píseň,“ vysvětlila Zvonilka. „Zpívají ji keporkačí pánové. Všichni v našem moři zpívají tu samou, tón po tónu. Jedna píseň trvá skoro tak dlouho jako celá pohádka. A pak ji zazpívají znovu. A zase znovu.“` },
      { t: `Pod hladinou bylo vidět velké tmavé stíny. Keporkačí zpěváci visí ve vodě skoro nehybně, hlavou dolů a ploutve roztažené, jako by poslouchali sami sebe. A zpívají a zpívají.` },
      { t: `„A proč vlastně zpívají?“ „To nikdo přesně neví,“ řekla Zvonilka. „Lidé si myslí, že tak pánové ukazují, kdo z nich je nejlepší zpěvák, a líbí se tím velrybím dámám. Ale já myslím, že je to prostě baví.“` },
      { t: `„A ty taky zpíváš?“ ${c.g('zeptal', 'zeptala', 'zeptali')} se ${c.H}.` },
      { t: `Zvonilka chvilku mlčela. „Zpívám. Ale jinak. Takhle.“ A zazpívala: cink, ciri, cink, cink. Vysoko a krátce, jako zvonek na kole.` },
      { t: `Z hloubky se ozvalo zabručení. To byl starý keporkak Hlubák, nejhlubší hlas z celého sboru. „Zvonilko, takhle se nezpívá. Píseň má být dlouhá a hluboká. Zpívej pořádně, nebo nezpívej.“` },
      { t: `„Já to zkoušela,“ zašeptala Zvonilka. Nadechla se, zanořila hlavu a zkusila to hluboko. Úúú… brlbrlbrlbrl. Vyšlo z ní jen velké bublání, jako když se fouká brčkem do kakaa.` },
      { t: `Pár ryb se zachichotalo. Zvonilka se zastyděla. Od té doby zpívala jen potichu, sama pro sebe, když ji nikdo neslyšel.` },
      { t: `Jen jedna stará mořská želva ji poslouchala ráda. Připlouvala vždycky, když Zvonilka zpívala, a kývala do taktu vrásčitou hlavou. „Slyšela jsem za svůj život tisíc písní,“ říkávala. „Ale tvou bych poznala i ze spaní.“` },
      { t: `„${c.n('Mně', 'Nám')} se tvoje písnička líbí,“ ${c.g('řekl', 'řekla', 'řekli')} ${c.H}. „Je veselá. A hned se pozná.“` },
      { t: `Zvonilka se poprvé usmála. A když se usměje velryba, je to pořádně velký úsměv.` },
      { t: `Pak spolu ${c.g('plavali', 'plavaly', 'plavali', 'plavaly')} dál, pomalu a po hladině, aby nikdo nespadl. Kolem vyskakovaly létající ryby, malé a stříbrné, a plachtily nad vodou jako vlaštovky. Za nimi se ve vodě rozsvěcovaly drobounké modré jiskřičky. Voda byla teplá jako ve vaně a voněla solí.` },
      { t: `Chvíli s nimi plavala parta delfínů. Vyskakovali z vody v obloučcích, jeden za druhým, a hvízdali na pozdrav. Delfíni jsou příbuzní velryb, jen mnohem menší a mnohem upovídanější.` },
      { t: `Keporkaci tráví léto daleko, ve studeném moři, kde je spousta potravy. Jedí tam malinké korýšky a rybičky a jedním douškem spolknou celé hejno. Na zimu ale připlouvají sem, do teplého moře. Tady se jim rodí mláďata.` },
      { t: `Najednou se kus od nich vymrštila z vody obrovská velryba, celá, až k ocasu. A pak – žbluňk! – dopadla zpátky a voda vystříkla až k měsíci. „To je Hlubák,“ zasmála se Zvonilka. „Keporkaci rádi vyskakují. Nikdo přesně neví proč. Možná jen tak, pro radost.“`, sfx: 'wind' },
      { t: `Za chvíli ${c.g('doplavali', 'doplavaly', 'doplavali', 'doplavaly')} k velké velrybě, která odpočívala na hladině jako tmavý ostrov. To byla Vlna, Zvonilčina teta. Velryby nikdy nespí tvrdě jako lidé. Jen si zdřímnou u hladiny, aby se mohly kdykoli nadechnout.` },
      { t: `„Teta Vlna má mládě,“ šeptala Zvonilka. „Jmenuje se Šplouch. Je mu teprve pár týdnů, a už je dlouhý jako auto. Pije maminčino mléko a roste tak rychle, že to skoro slyšíš.“` },
      { t: `Jenže vedle Vlny žádné mládě nebylo.` },
      { t: `Vlna se právě probudila. Rozhlédla se vlevo, vpravo, pod sebe. „Šplouchu? Šplouchu!“ Zavolala ho, ale potichu. Velrybí maminky mluví na mláďata skoro šeptem, aby je slyšelo jen jejich mládě.` },
      { t: `„Usnula jsem jen na chvilku,“ naříkala. „A on je tak zvědavý. Určitě plaval za létajícími rybami.“ Šeptala a šeptala. Jenže Šplouch byl moc daleko a šepot se k němu nedonesl.` },
      { t: `Celý sbor hned přestal zpívat. „Budeme volat tak nahlas, jak to jen jde,“ rozhodl Hlubák. „Šplouch nás uslyší a připlave.“` },
      { t: `A zpívali. Úúú, óóó, mmmm. Tak hluboko a tak silně, že se voda chvěla. Velrybí písně jsou slyšet strašně daleko. Pod vodou je slyší i velryby, které plavou mnoho kilometrů odtud.` },
      { t: `Zpívali dlouho. Vlna kroužila kolem a vyhlížela. Zvonilka se nervózně kolébala na vlnách. A měsíc se pomalu posouval po obloze.` },
      { t: `Ale Šplouch nepřiplaval.` },
      { t: `${c.H} ${c.g('ponořil', 'ponořila', 'ponořili')} mušli do vody a ${c.g('přiložil', 'přiložila', 'přiložili')} ji k uchu.` },
      { t: `V kouzelné mušli bylo všechno, co se děje pod hladinou, slyšet jasně a zblízka. A najednou to bylo jasné. Velká píseň byla všude. Zleva, zprava, zezdola, zezadu. Jako ozvěna v tělocvičně. Kdo by se podle ní chtěl řídit, vůbec by nevěděl, kam plavat.` },
      { t: `„Prosím, buďte chvilku zticha!“ ${c.g('zavolal', 'zavolala', 'zavolali')} ${c.H}.` },
      { t: `Hlubák se tak podivil, že ${c.n('malé dítě okřiklo', 'malé děti okřikly')} celý velrybí sbor, až zapomněl zavřít pusu. Ale ztichl. A s ním ztichlo celé moře.` },
      { t: `${c.H} ${c.g('poslouchal', 'poslouchala', 'poslouchali')}.` },
      { t: `Šplouchání vln. Pískání delfínů někde daleko. A pak, úplně slaboučce, zprava, od skal: „Mmmami?“`, pause: 2 },
      { t: `„Jak to, že ho ${c.n('slyšíš', 'slyšíte')}, a my ne?“ zabručel Hlubák. „Protože jste byli zticha,“ zněla odpověď. A Hlubák se poprvé po dlouhých letech hluboce zamyslel.` },
      { t: `„Tam!“ Zvonilka se otočila a plavala ke skalám, co jí ploutve stačily. Držet se, pevně držet!` },
      { t: `Skály byly černé a mokré a vlny do nich pleskaly. Plesk, plesk. Zvonilka plavala opatrně a pomalu, aby se o ně neodřela.` },
      { t: `U skal, kde se vlny tříštily o kameny, se na hladině houpal Šplouch. Byl unavený, vyděšený a fňukal do vody malé bublinky. Létající ryby mu dávno uletěly.` },
      { t: `Aspoň že zůstal u hladiny. Mláďata se musí nadechovat mnohem častěji než velké velryby, a tak se Šplouch každou chvíli vynořil a vyfoukl malý, ustaraný obláček.` },
      { t: `„Pojď, odvedu tě k mamince,“ řekla Zvonilka. Jenže Šplouch se nechtěl hnout. „Nemůžu, už nemám sílu. Je tma, moře je velké a já neslyším maminku.“` },
      { t: `Maminka musí připlavat sem. Ale jak ji sem dovést? ${c.H} se ${c.g('zamyslel', 'zamyslela', 'zamysleli')}.` },
      { t: `Velká píseň je všude, a proto se podle ní nic najít nedá. Šepot je moc slabý a daleko nedoletí. Ale jedna písnička je v celém moři jiná než všechny ostatní. Vysoká, krátká a hned se pozná.` },
      { t: `„Zvonilko, zpívej! Svou písničku, tu, co je jenom tvoje. Teta Vlna ji zná a pozná ji odkudkoli. A když ji uslyší jenom odsud, bude vědět, kam plavat.“` },
      { t: `Zvonilka se zhluboka nadechla. A zpívala. Cink, ciri, cink, cink. Vysoko a jasně, přes vlny, přes tmu, přes celé tiché moře.`, sfx: 'sparkle' },
      { t: `Zpívala jednou, dvakrát, desetkrát. Hlas se jí trochu třásl. Ale nepřestala.` },
      { t: `Šplouch přestal fňukat a poslouchal. Ta písnička byla tak veselá, že se při ní nedalo bát.` },
      { t: `A daleko, daleko zvedla Vlna hlavu z vody. Uslyšela jedinou písničku, která v celém moři zněla jinak. A plavala za ní. Rovně, rychle a bez bloudění.` },
      { t: `Když se ze tmy vynořila velká maminčina hlava, Šplouch radostí vypískl. Přitiskl se k mamince bokem a maminka ho objala ploutví. Dlouhou bílou ploutví, jako křídlem.` },
      { t: `Hned se napil mléka. Pak vyfoukl malou fontánku, fííí, a byl zase docela spokojený.` },
      { t: `Vlna se podívala na ${c.g('malého cestujícího', 'malou cestující', 'malé cestující', 'malé cestující')} na Zvonilčiných zádech. Pak dlouze a vděčně vydechla. Fííí. Ve velrybí řeči je to to nejhlubší děkuju.` },
      { t: `Mezitím připlul i Hlubák s celým sborem. Dlouho se díval na Zvonilku. Pak řekl tím svým nejhlubším hlasem: „Kdybys zpívala jako my, Vlna by vás v našem zpěvu nikdy nenašla.“` },
      { t: `Z hlubiny se vynořila i stará želva. Jen kývla vrásčitou hlavou a usmála se. „Já to říkala. Tuhle písničku člověk pozná i ze spaní.“` },
      { t: `Keporkačí píseň se totiž každý rok trochu mění. Někdo do ní přidá nový kousek, ostatní se ho naučí a za čas ho zpívá celé moře.` },
      { t: `A tak se do Velké písně ten rok dostal úplně nový kousek. Vysoký a krátký. Cink, ciri, cink. A zpíval ho i Hlubák, i když mu to trochu bublalo.` },
      { t: `„Děkuju,“ řekla Zvonilka. „${c.n('Tys', 'Vy jste')} mě ${c.g('slyšel', 'slyšela', 'slyšeli')}, i když mě nikdo neposlouchal.“ A pak zazpívala tu nejtišší písničku, jakou kdy zpívala. Ukolébavku.` },
      { t: `Pak Zvonilka zvedla nad vodu ocas, ten s inkoustovými skvrnkami, a zamávala jím na rozloučenou. Takový ocas nemá na světě nikdo jiný. Stejně jako takovou písničku.` },
      { t: `Šplouch usnul první, přitulený k mamince. Pak Vlna. Stará želva zívla a zmizela v hlubině. A i velrybí pánové zpívali Velkou píseň čím dál pomaleji a tišeji, jako když se zpívá dětem.` },
      { t: `Moře se houpalo. Vlny šuměly. Šššš. Měsíc se pomalu sklonil k vodě a víčka byla čím dál těžší.`, pause: 2 },
      { t: `Když ${c.H} zase ${c.g('otevřel', 'otevřela', 'otevřeli')} oči, ${c.g('ležel', 'ležela', 'leželi')} v posteli.` },
      { t: `Mušle ležela na polštáři a byla ještě trochu slaná. Šššš, šumělo v ní moře. A někde hluboko, úplně potichu: cink, ciri, cink.`, pause: 3 },
      { t: `Dobrou noc, Zvonilko. Dobrou noc, Šplouchu. Dobrou noc, ${c.h.voc}.`, pause: 4 },
    ],
  },
  {
    id: 'svetluska',
    delka: 5,
    pro: 'vse',
    pozn: 'Nejmenší světluška Drobka svítí tak slabě, že ji ostatní pobízejí, ať přidá. Beruška Tečka se večer ztratí a velké světlušky jsou na ni moc jasné a rychlé. Dítě z okna poradí Drobce, ať letí nízko a svítí jen na jeden krůček – a beruška tak dojde domů. Pak Drobka svítí na parapetu jako noční světýlko a dítě usne.',
    pouceni: 'I malé světlo pomůže, když svítí tam, kde je ho potřeba; a v noci stačí světla málo.',
    free: false,
    cats: ['noc', 'zvirata'],
    ages: [2, 6],
    mood: 'lullaby',
    cover: { emoji: '✨', g1: '#1b2a49', g2: '#c6ff00' },
    title: () => `Světluška, která svítila málo`,
    text: (c) => [
      { t: `Byl teplý letní večer. Okno v pokojíčku bylo otevřené a dovnitř voněla posekaná tráva. Někde v trávě cvrčel cvrček, cvrk, cvrk, jako by natahoval malé hodinky.` },
      { t: `${c.H} ${c.g('ležel', 'ležela', 'leželi')} v posteli a ${c.g('díval', 'dívala', 'dívali')} se ven.` },
      { t: `Nad zahradou se rozsvěcovala malá světýlka. Jedno, druhé, deset, sto. Plula vzduchem a pomalu blikala.`, sfx: 'sparkle' },
      { t: `„To jsou světlušky,“ ${c.p1.g('zašeptal', 'zašeptala')} ${c.p1.nom}.` },
      { t: `„Svítí jen pár teplých týdnů v roce, na začátku léta. Říká se jim taky svatojánské mušky, i když to vlastně nejsou mušky, ale malí brouci.“` },
      { t: `Světlušky svítí zadečkem. Opravdu! A jejich světlo nehřeje ani nepálí. Je studené jako světlo měsíce. Blikáním si světlušky povídají. Blik znamená: Ahoj, tady jsem.` },
      { t: `Mezi světluškami létala jedna úplně nejmenší. Jmenovala se Drobka. Svítila tak slabounce, že vedle ostatních vypadala jako drobeček světla, který někdo zapomněl zhasnout.` },
      { t: `„Drobko, přidej!“ volaly na ni velké světlušky. „Takhle tě nikdo neuvidí!“ Drobka se snažila, až se celá chvěla. Ale víc to nešlo.` },
      { t: `Tak si sedla na stéblo trávy a posmutněla. K čemu je světluška, která skoro nesvítí? Velké světlušky tančily nahoře, vysoko nad keři. A ona tu seděla dole, sama, s tím svým drobečkem světla.` },
      { t: `Vtom se dole na cestičce ozvalo tiché popotahování. Na kamínku seděla beruška Tečka. Celý den lezla po zahradě a hledala mšice, a teď nemohla trefit domů. Na růžový keř pod oknem.` },
      { t: `„Je tma,“ fňukala Tečka. „Nevidím ani na svoje nožičky.“` },
      { t: `Velké světlušky hned přiletěly. Zakroužily nad ní, zablikaly a zajiskřily. Bylo to krásné, ale tak jasné a tak rychlé, že Tečka jen mžourala. A než se rozkoukala, světlušky byly zase vysoko a tančily dál.` },
      { t: `Tohle všechno ${c.g('viděl', 'viděla', 'viděli')} z okna ${c.H}.` },
      { t: `A ${c.g('dostal', 'dostala', 'dostali')} nápad. „Drobko,“ ${c.g('zašeptal', 'zašeptala', 'zašeptali')} do tmy. „Poleť dolů, úplně nízko, k berušce. A neleť rychle. Sviť jí jen na jeden krůček. Víc nepotřebuje.“` },
      { t: `Drobka se snesla k zemi. Těsně nad cestičku, kousek před Tečku. A blikla.` },
      { t: `Blik. Pod nožičkami se objevil kamínek. Tečka udělala krůček. Blik. Stéblo trávy. Krůček. Blik. Spadlý lísteček. Krůček.` },
      { t: `Blik, krůček. Blik, krůček. Drobka svítila pořád stejně slabounce. Ale přesně tam, kam bylo potřeba.` },
      { t: `A pak se ve světýlku objevil trn a zelený list. Růžový keř! Tečka vylezla po stonku nahoru, schovala se pod lísteček a složila krovky. „Děkuju, Drobko,“ zašeptala ospale. „Tvoje světlo je přesně tak velké, jak má být.“` },
      { t: `Velké světlušky slétly dolů a divily se. „Drobko, jak jsi to dokázala?“ „Svítila jsem jen na jeden krůček,“ odpověděla Drobka. A poprvé za celý večer zablikala docela hrdě.` },
      { t: `Drobka pak vyletěla k oknu a posadila se na parapet. Svítila malým, měkkým světýlkem. Jako lampička, která se nechává svítit na noc. Na stropě se od ní houpal malý světelný kroužek, sem a tam, jako by tam něco tiše dýchalo.` },
      { t: `${c.H} se ${c.g('usmál', 'usmála', 'usmáli')}.` },
      { t: `I v pokojíčku přece stačí malé světlo. Takové, aby bylo vidět, kde jsou dveře a kde je polštář. Víc v noci není potřeba.` },
      { t: `Venku zatím zhasínaly velké světlušky, jedna po druhé. Utancovaly se a šly spát do trávy.` },
      { t: `Jen Drobka ještě chvilku svítila. Blik. A pomaleji. Blik. A ještě pomaleji.`, pause: 3 },
      { t: `${c.n('Zavři', 'Zavřete')} oči. Jako beruška pod lístečkem. Jako světluška v trávě. Blik… a tma. Měkká, tichá, letní tma.`, pause: 4 },
      { t: `Dobrou noc, Drobko. Dobrou noc, ${c.h.voc}.`, pause: 4 },
    ],
  },
  {
    id: 'mesto-usina',
    delka: 5,
    pro: 'vse',
    pozn: 'Ukolébavka: obec, kde dítě bydlí, se večer postupně ukládá ke spánku. Obchod zamyká, poslední autobus si na konečné oddechne, kos dozpívá, pejsek zaleze do boudy, kočka a lampy drží noční hlídku, pekař spí naruby a okna zhasínají, až zbývá jen to dětské. Refrén „Zhasnout, zívnout, spát.“',
    pouceni: 'Večer přichází odpočinek pro všechny: i lidé, auta a zvířata kolem nás jdou spát, aby ráno měli sílu.',
    free: false,
    cats: ['noc'],
    ages: [2, 6],
    mood: 'lullaby',
    cover: { emoji: '🏘️', g1: '#283593', g2: '#ffab91' },
    title: () => `Jak u nás všechno usíná`,
    text: (c) => [
      { t: `Slunce už je nízko. Klouže po střechách, po komínech a po anténách. Pak se schová za kopec a nebe zrůžoví jako tvářičky po koupání.` },
      { t: `${cap(c.inTown)} začíná večer.` },
      { t: `A všechno, co celý den běhalo, jezdilo, prodávalo a štěbetalo, se pomalu chystá spát.` },
      { t: `V obchodě na rohu si poslední zákazník koupil mléko na ráno. Paní prodavačka spočítala rohlíky, které zbyly, zhasla světla a zamkla dveře. Cvak.` },
      { t: `Zhasnout, zívnout, spát.`, pause: 1 },
      { t: `Ulicí projíždí poslední autobus. Je skoro prázdný, jen vzadu dřímá jeden pán s taškou. Autobus dojede na konečnou, otevře dveře a vydechne: pššš. Jako když si někdo sedne po dlouhém dni.`, sfx: 'car' },
      { t: `Pan řidič mu poplácá volant: „Dobrou noc, kamaráde.“ Zhasnout, zívnout, spát.` },
      { t: `Na hřišti se ještě chvilku houpe houpačka. Sama od sebe, jen tak, ve větru. Pak se zastaví. V pískovišti zůstala zapomenutá lopatka. Bude tam čekat až do rána, pod peřinou z písku.` },
      { t: `Na nejvyšší anténě sedí kos. Zpívá poslední písničku dne, tu nejkrásnější. Kosi zpívají nejradši brzy ráno a večer, když všude ztichne.`, sfx: 'birds' },
      { t: `Pak se vrabci schovají pod střechy, holubi se načepýří na římse a kos si zastrčí zobáček do peří. Zhasnout, zívnout, spát.` },
      { t: `Na zahradách se zavírají kurníky. Slepice sedí na bidýlku, jedna vedle druhé, jako korálky na šňůrce. Kohout je ještě jednou spočítá, jestli jsou všechny doma. Zhasnout, zívnout, spát.` },
      { t: `Pejsek u sousedů zívne tak, až mu cvaknou zuby. Zaleze do boudy a stočí se do klubíčka, čumák pod ocas.` },
      { t: `Jen kočka se protáhne a vyjde ven. Kočky totiž chodí na obchůzku v noci. Projde se po plotě, zkontroluje všechny zahrady a ráno se vyspí za všechny.` },
      { t: `Ve školce je už dávno zavřeno. Na věšáčcích nevisí žádné bundy, jen jedna zapomenutá čepice. Postýlky pro polední spaní jsou složené a plyšáci sedí v řadě na poličce. Zhasnout, zívnout, spát.` },
      { t: `Někde v dálce odbíjejí hodiny. Bim, bam. Bim, bam. A po silnici projede poslední auto, pomalu a tiše, jako by jelo po špičkách.` },
      { t: `Na ulici se rozsvítí lampy. Jedna, druhá, třetí. Lampy nespí. Svítí tiše a tlumeně, jako noční světýlko pro celou ulici, aby noc věděla, kudy chodit.` },
      { t: `A ${c.n('víš', 'víte')}, kdo jde spát úplně první? Pan pekař. Pekař spí naruby. Jde do postele, když ještě není tma, a vstává, když ještě není světlo. Aby ráno voněly rohlíky.` },
      { t: `Okna v domech zhasínají jedno po druhém. Tady modré světlo od televize. Tamhle žlutá lampička nad knížkou. Cvak, cvak. Zhasnout, zívnout, spát.` },
      { t: c.near.length ? `A stejně usíná celé okolí: ${listCz(c.near.slice(0, 3))}. Všude zhasínají okna a všude se ukládají děti.` : `A stejně usínají i vesnice a města kolem. Všude zhasínají okna a všude se ukládají děti.` },
      { t: `Nad střechami vychází měsíc. Kulatý a klidný. Dívá se dolů na ulice, na zahrady a na střechy. A počítá, jestli už všichni spí. Kolem něj se rozsvěcují hvězdy, jedna za druhou, jako okna v nebeských domečcích.` },
      { t: `Jedno okno ale ještě svítí. Úplně poslední. To je okno ${c.h.gen}.` },
      { t: `${cap(c.p1.nom)} ${c.p1.g('urovnal', 'urovnala')} peřinu a ${c.p1.g('dal', 'dala')} pusu na dobrou noc.` },
      { t: `Obchod spí. Autobus spí. Houpačka a lopatka spí. Kos spí, pejsek spí. Jen kočka a lampy tiše hlídají.`, pause: 2 },
      { t: `A teď už ${c.n('můžeš', 'můžete')} spát i ${c.n('ty', 'vy')}. Cvak. Zhasnout, zívnout, spát.`, pause: 4 },
      { t: `Dobrou noc, ${c.h.voc}.`, pause: 4 },
    ],
  },
]);
